// Core tests: the 19 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC's tests section. Every expected value below was computed by hand
// from the SPEC's rules; the property section also recomputes the
// results with an independent BigInt implementation written from the
// SPEC text (not from the product code).

import assert from "node:assert/strict";
import test from "node:test";
import { run } from "../public/js/core/steps.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  steps: "10000",
  strideSource: "height",
  strideCm: "70",
  heightCm: "170",
  calories: "off",
  weightKg: "65",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

function resultOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, true, JSON.stringify(outcome));
  return outcome.result;
}

test("legal endpoints: steps 0 and 99,999,999, stride 20 and 150, height 80 and 250, weight 20 and 500", () => {
  assert.deepEqual(
    resultOf({ ...base, steps: "0", strideSource: "measured", strideCm: "20" }),
    { strideCm: 20, distanceKm: 0, stepsPerKm: 5000, caloriesKcal: null },
  );
  assert.deepEqual(
    resultOf({ ...base, steps: "99999999", strideSource: "measured", strideCm: "150" }),
    { strideCm: 150, distanceKm: 150000, stepsPerKm: 667, caloriesKcal: null },
  );
  assert.deepEqual(
    resultOf({ ...base, heightCm: "80" }),
    { strideCm: 33.1, distanceKm: 3.31, stepsPerKm: 3019, caloriesKcal: null },
  );
  assert.deepEqual(
    resultOf({ ...base, heightCm: "250" }),
    { strideCm: 103.5, distanceKm: 10.35, stepsPerKm: 966, caloriesKcal: null },
  );
  assert.deepEqual(
    resultOf({ ...base, calories: "on", weightKg: "20" }),
    { strideCm: 70.4, distanceKm: 7.04, stepsPerKm: 1421, caloriesKcal: 106 },
  );
  assert.deepEqual(
    resultOf({ ...base, calories: "on", weightKg: "500" }),
    { strideCm: 70.4, distanceKm: 7.04, stepsPerKm: 1421, caloriesKcal: 2639 },
  );
});

test("decimal endpoints are inclusive: stride 150.00, height 250.0, weight 500.0", () => {
  assert.deepEqual(
    resultOf({ ...base, steps: "1000", strideSource: "measured", strideCm: "150.00" }),
    { strideCm: 150, distanceKm: 1.5, stepsPerKm: 667, caloriesKcal: null },
  );
  assert.deepEqual(
    resultOf({ ...base, steps: "1000", heightCm: "250.0" }),
    { strideCm: 103.5, distanceKm: 1.04, stepsPerKm: 966, caloriesKcal: null },
  );
  assert.deepEqual(
    resultOf({ ...base, calories: "on", weightKg: "500.0" }).caloriesKcal,
    2639,
  );
});

test("just over the limits: stride 19.9/150.1, height 79.9/250.1, weight 19.9/500.1 are RANGE; a 9-digit step count is INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ ...base, strideSource: "measured", strideCm: "19.9" }), {
    code: "RANGE",
    field: "strideCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, strideSource: "measured", strideCm: "150.1" }), {
    code: "RANGE",
    field: "strideCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, heightCm: "79.9" }), {
    code: "RANGE",
    field: "heightCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, heightCm: "250.1" }), {
    code: "RANGE",
    field: "heightCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, calories: "on", weightKg: "19.9" }), {
    code: "RANGE",
    field: "weightKg",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, calories: "on", weightKg: "500.1" }), {
    code: "RANGE",
    field: "weightKg",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, steps: "100000000" }), {
    code: "INPUT_LIMIT",
    field: "steps",
    row: null,
  });
});

test("integer grammar: commas, spaces, signs, and full-width digits are INTEGER_FORMAT", () => {
  for (const steps of ["1,000", " 100", "100 ", "+100", "-100", "１２３"]) {
    assert.deepEqual(errorOf({ ...base, steps }), {
      code: "INTEGER_FORMAT",
      field: "steps",
      row: null,
    });
  }
});

test("decimal grammar: a trailing dot, a missing integer part, and too many decimal places are DECIMAL_FORMAT", () => {
  assert.deepEqual(errorOf({ ...base, strideSource: "measured", strideCm: "70." }), {
    code: "DECIMAL_FORMAT",
    field: "strideCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, strideSource: "measured", strideCm: ".70" }), {
    code: "DECIMAL_FORMAT",
    field: "strideCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, strideSource: "measured", strideCm: "70.123" }), {
    code: "DECIMAL_FORMAT",
    field: "strideCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, calories: "on", weightKg: "65.55" }), {
    code: "DECIMAL_FORMAT",
    field: "weightKg",
    row: null,
  });
});

test("empty active fields are EMPTY; enum fields are EMPTY before ENUM", () => {
  assert.deepEqual(errorOf({ ...base, steps: "" }), { code: "EMPTY", field: "steps", row: null });
  assert.deepEqual(errorOf({ ...base, strideSource: "measured", strideCm: "" }), {
    code: "EMPTY",
    field: "strideCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, heightCm: "" }), {
    code: "EMPTY",
    field: "heightCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, strideSource: "" }), {
    code: "EMPTY",
    field: "strideSource",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, strideSource: "HEIGHT" }), {
    code: "ENUM",
    field: "strideSource",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, calories: "" }), {
    code: "EMPTY",
    field: "calories",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, calories: "ON" }), {
    code: "ENUM",
    field: "calories",
    row: null,
  });
});

test("inactive fields are ignored except INPUT_LIMIT and UNICODE", () => {
  // Empty or garbage inactive values are ignored entirely.
  assert.deepEqual(resultOf({ ...base, strideCm: "" }), {
    strideCm: 70.4,
    distanceKm: 7.04,
    stepsPerKm: 1421,
    caloriesKcal: null,
  });
  assert.deepEqual(
    resultOf({ ...base, steps: "5000", strideSource: "measured", strideCm: "65.5", heightCm: "abc" }),
    { strideCm: 65.5, distanceKm: 3.28, stepsPerKm: 1527, caloriesKcal: null },
  );
  assert.deepEqual(resultOf({ ...base, weightKg: "" }), {
    strideCm: 70.4,
    distanceKm: 7.04,
    stepsPerKm: 1421,
    caloriesKcal: null,
  });
  // ...but a lone surrogate in an inactive field is still UNICODE.
  assert.deepEqual(errorOf({ ...base, strideCm: "\uD800" }), {
    code: "UNICODE",
    field: "strideCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, strideSource: "measured", heightCm: "\uD800" }), {
    code: "UNICODE",
    field: "heightCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, weightKg: "\uD800" }), {
    code: "UNICODE",
    field: "weightKg",
    row: null,
  });
  // ...and an over-long inactive value is still INPUT_LIMIT.
  assert.deepEqual(errorOf({ ...base, strideCm: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "strideCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, weightKg: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "weightKg",
    row: null,
  });
});

test("an active field reports UNICODE before EMPTY and grammar", () => {
  assert.deepEqual(errorOf({ ...base, steps: "\uD800" }), {
    code: "UNICODE",
    field: "steps",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, strideSource: "measured", strideCm: "\uD800" }), {
    code: "UNICODE",
    field: "strideCm",
    row: null,
  });
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...base, steps: "100.5", strideSource: "auto" }), {
    code: "INTEGER_FORMAT",
    field: "steps",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, strideSource: "auto", strideCm: "999" }), {
    code: "ENUM",
    field: "strideSource",
    row: null,
  });
  assert.deepEqual(
    errorOf({ ...base, strideSource: "measured", strideCm: "160", calories: "on", weightKg: "abc" }),
    { code: "RANGE", field: "strideCm", row: null },
  );
  assert.deepEqual(errorOf({ ...base, heightCm: "260", calories: "maybe" }), {
    code: "RANGE",
    field: "heightCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, calories: "maybe", weightKg: "abc" }), {
    code: "ENUM",
    field: "calories",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, string, and accessor are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.weightKg;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, steps: 10000 }), schema);
  assert.deepEqual(errorOf({ ...base, calories: true }), schema);
  assert.deepEqual(errorOf(["10000"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("10000"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "steps", {
    enumerable: true,
    get() {
      return "10000";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
});

test("property: distance is monotone non-decreasing in steps and in stride; calories in weight", () => {
  const bySteps = ["0", "1", "100", "10000", "99999999"].map(
    (steps) => resultOf({ ...base, steps }).distanceKm,
  );
  for (let i = 1; i < bySteps.length; i += 1) assert.ok(bySteps[i] >= bySteps[i - 1]);
  const byStride = ["20", "50", "100", "150"].map(
    (strideCm) => resultOf({ ...base, strideSource: "measured", strideCm }).distanceKm,
  );
  for (let i = 1; i < byStride.length; i += 1) assert.ok(byStride[i] >= byStride[i - 1]);
  const byWeight = ["20", "65", "100", "500"].map(
    (weightKg) => resultOf({ ...base, calories: "on", weightKg }).caloriesKcal,
  );
  for (let i = 1; i < byWeight.length; i += 1) assert.ok(byWeight[i] >= byWeight[i - 1]);
});

// --- Independent recomputation, written from the SPEC text ----------
// Parse a decimal string into an exact BigInt fraction.
function fractionOf(raw) {
  const [whole, fraction = ""] = raw.split(".");
  return { num: BigInt(whole + fraction), den: 10n ** BigInt(fraction.length) };
}
function roundHalfUp(num, den) {
  return (2n * num + den) / (2n * den);
}
function roundedNumber(num, den, places) {
  const scale = 10n ** BigInt(places);
  return Number(roundHalfUp(num * scale, den)) / Number(scale);
}
// Recompute a result from the SPEC formulas only: stride is the
// measured value or height x 207/500; distance is steps x stride /
// 100,000; calories are 3/4 x weight x the unrounded distance.
function recompute(input) {
  const stride =
    input.strideSource === "measured"
      ? fractionOf(input.strideCm)
      : (() => {
          const h = fractionOf(input.heightCm);
          return { num: h.num * 207n, den: h.den * 500n };
        })();
  const steps = BigInt(input.steps);
  const distanceNum = steps * stride.num;
  const distanceDen = stride.den * 100000n;
  let caloriesKcal = null;
  if (input.calories === "on") {
    const w = fractionOf(input.weightKg);
    caloriesKcal = Number(
      roundHalfUp(3n * w.num * distanceNum, 4n * w.den * distanceDen),
    );
  }
  return {
    strideCm: roundedNumber(stride.num, stride.den, 1),
    distanceKm: roundedNumber(distanceNum, distanceDen, 2),
    stepsPerKm: Number(roundHalfUp(100000n * stride.den, stride.num)),
    caloriesKcal,
  };
}

test("independent recomputation: the SPEC formulas reproduce every successful fixture", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    assert.deepEqual(recompute(entry.input), entry.expected.result, entry.id);
  }
});

test("property: stepsPerKm x exact stride is within one stride of 100,000", () => {
  const inputs = [
    base,
    { ...base, heightCm: "171", steps: "3000" },
    { ...base, strideSource: "measured", strideCm: "72.25", steps: "12000" },
    { ...base, strideSource: "measured", strideCm: "20", steps: "1" },
    { ...base, heightCm: "250", steps: "99999999" },
  ];
  for (const input of inputs) {
    const result = resultOf(input);
    const stride =
      input.strideSource === "measured"
        ? fractionOf(input.strideCm)
        : (() => {
            const h = fractionOf(input.heightCm);
            return { num: h.num * 207n, den: h.den * 500n };
          })();
    // |stepsPerKm * stride - 100000| < stride, in exact BigInt terms.
    const diff = BigInt(result.stepsPerKm) * stride.num - 100000n * stride.den;
    const abs = diff < 0n ? -diff : diff;
    assert.ok(abs < stride.num, JSON.stringify(input));
  }
});
